#include "hal/gpio.h"
#include "hal/systick.h"
#include "stm32f407xx.h"
#include <stdint.h>

int main(void) {
  initLed();
  systick_init();

  uint8_t led_on = 0;
  uint32_t start_tick = 0u;

  for (;;) {
    static const uint32_t FLASH_PERIOD_MS = 1000u;
    if ((systick_get_ms() - start_tick) >= FLASH_PERIOD_MS) {
      start_tick += FLASH_PERIOD_MS;
      if (led_on == 0u) {
        orangeLedOn();
        led_on = 1;
      } else {
        orangeLedOff();
        led_on = 0;
      }
    }
    __WFI();
  }
}